B.ac5=s(["\u0406 \u0442\u049b\u0441.","\u0406\u0406 \u0442\u049b\u0441.","\u0406\u0406\u0406 \u0442\u049b\u0441.","IV \u0442\u049b\u0441."],t.s)
B.a7h=s(["1 reife Banane","150 g Haferflocken","1 Ei"],t.s)
B.a81=s(["Backofen auf 180 Grad C vorheizen.","Banane zerdruecken, mit Haferflocken und Ei verkneten.","Kleine Taler formen, auf Backblech mit Backpapier setzen.","15-18 Minuten backen, bis sie fest sind. Auskuehlen lassen."],t.s)
B.ax7=new A.hC(B.jM,"Bananen-Hafer-Kekse","3 Zutaten, schnell gemacht",B.a7h,B.a81,"In einer Dose ca. 1 Woche, eingefroren laenger.","Fuer kleine Hunde die Taler besonders duenn ausrollen.")
B.aa4=s(["1 Dose Thunfisch im eigenen Saft (ohne Salz/Oel abgegossen)","1 Ei","4-5 EL Haferflocken oder Reismehl"],t.s)
B.a7P=s(["Backofen auf 175 Grad C vorheizen.","Alles zu einer Masse verruehren.","Duenn auf ein Backblech streichen.","15 Minuten backen, abkuehlen, in kleine Wuerfel schneiden."],t.s)
B.ax6=new A.hC(B.jM,"Thunfisch-Wuerfel","Herzhaft und sehr beliebt",B.aa4,B.a7P,"Im Kuehlschrank 3-4 Tage, einfrieren moeglich.","Perfekt als hochwertiges Trainings-Leckerli.")
B.aaD=s(["150 g Kuerbispuree (ungesuesst, ohne Gewuerze)","200 g Vollkornmehl oder Haferflocken","1 Ei"],t.s)
B.a5L=s(["Backofen auf 180 Grad C vorheizen.","Zutaten zu einem Teig verkneten, ggf. etwas Mehl ergaenzen.","Ausrollen und Formen ausstechen.","20 Minuten backen, bis sie knusprig sind."],t.s)
B.ax4=new A.hC(B.jM,"Kuerbis-Kekse","Gut fuer die Verdauung",B.aaD,B.a5L,"Trocken gelagert 1-2 Wochen.",null)
B.ad2=s(["1 geraspelte Karotte","1/2 geraspelter Apfel (ohne Kerngehaeuse)","150 g Haferflocken","1 Ei"],t.s)
B.aak=s(["Backofen auf 180 Grad C vorheizen.","Alles vermengen, kleine Taler formen.","18-20 Minuten backen, auskuehlen lassen."],t.s)
B.ax8=new A.hC(B.jM,"Karotten-Apfel-Taler","Vitaminreich",B.ad2,B.aak,"In einer Dose ca. 1 Woche.",null)
B.aaS=s(["3 EL Magerquark","frische Petersilie, fein gehackt","Haferflocken zum Binden"],t.s)
B.a5Q=s(["Quark mit Petersilie verruehren.","So viele Haferflocken einkneten, bis eine formbare Masse entsteht.","Kleine Baellchen rollen."],t.s)
B.ax3=new A.hC(B.tm,"Quark-Kraeuter-Baellchen","In 5 Minuten fertig",B.aaS,B.a5Q,"Im Kuehlschrank 2-3 Tage.","Petersilie hilft sogar gegen Mundgeruch.")
B.a7g=s(["2 EL Erdnussbutter (OHNE Xylit/Suessstoff, ungesalzen)","Haferflocken"],t.s)
B.a9E=s(["Erdnussbutter mit so vielen Haferflocken verkneten, bis es formbar ist.","Kleine Kugeln rollen und kurz kalt stellen."],t.s)
B.ax1=new A.hC(B.tm,"Erdnussbutter-Happen","Nur 2 Zutaten",B.a7g,B.a9E,"Im Kuehlschrank ca. 4 Tage.","WICHTIG: Erdnussbutter MUSS xylitfrei sein - Xylit ist giftig.")
B.a6o=s(["Naturjoghurt (ohne Zucker)","einige Heidelbeeren oder Himbeeren"],t.s)
B.ae2=s(["Joghurt mit den Beeren verruehren.","In eine Eiswuerfelform oder Silikonform fuellen.","Ueber Nacht einfrieren."],t.s)
B.awY=new A.hC(B.nz,"Joghurt-Beeren-Eis","Erfrischung fuer heisse Tage",B.a6o,B.ae2,"Im Gefrierfach mehrere Wochen.","Nur kleine Portionen geben - kalt und langsam schlecken lassen.")
B.a9z=s(["ungesalzene Gemuese- oder Huehnerbruehe (selbst gekocht, ohne Zwiebel)"],t.s)
B.af7=s(["Bruehe abkuehlen lassen.","In Eiswuerfelformen fuellen und einfrieren."],t.s)
B.ax0=new A.hC(B.nz,"Brueh-Eis","Herzhaft und fluessigkeitsspendend",B.a9z,B.af7,"Im Gefrierfach mehrere Wochen.","Niemals Fertigbruehe mit Salz/Zwiebel verwenden.")
B.af8=s(["etwas Magerquark oder Naturjoghurt","ein paar Haferflocken + Banane"],t.s)
B.aeG=s(["Kong-Spielzeug mit der Masse fuellen.","Ueber Nacht einfrieren.","An heissen Tagen oder bei Langeweile geben."],t.s)
B.awZ=new A.hC(B.nz,"Gefuellter Kong (gefroren)","Lange Beschaeftigung",B.af8,B.aeG,"Einzeln eingefroren mehrere Wochen.","Haelt aufgeregte Hunde lange und ruhig beschaeftigt.")
B.aeJ=s(["250 g Rinderleber","1 Ei","3-4 EL Haferflocken"],t.s)
B.a7v=s(["Leber puerieren, mit Ei und Haferflocken vermengen.","Duenn auf ein Backblech streichen.","Bei 170 Grad C ca. 20 Minuten backen.","Auskuehlen, in winzige Wuerfel schneiden."],t.s)
B.ax5=new A.hC(B.ny,"Leber-Wuerfel","Das Highlight im Training",B.aeJ,B.a7v,"Im Kuehlschrank 3 Tage, sonst portionsweise einfrieren.","Sehr intensiv - nur kleine Mengen, sonst Durchfall.")
